module pulse_detect #(
    parameter s0 = 2'b00,
    parameter s1 = 2'b01,
    parameter s2 = 2'b10,
    parameter s3 = 2'b11
) (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);

localparam S0 = 2'b00;
localparam S1 = 2'b01;
localparam S2 = 2'b10;
localparam S3 = 2'b11;

reg [1:0] state;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= S0;
    end else begin
        case (state)
            S0: begin
                if (data_in == 1'b0) state <= S1;
                else state <= S0;
            end
            S1: begin
                if (data_in == 1'b1) state <= S2;
                else state <= S0;
            end
            S2: begin
                if (data_in == 1'b0) state <= S3;
                else state <= S0;
            end
            S3: begin
                if (data_in == 1'b1) state <= S2;
                else state <= S0;
            end
            default: state <= S0;
        endcase
    end
end

always @(*) begin
    case (state)
        S2: data_out = ~data_in;
        default: data_out = 1'b0;
    endcase
end

endmodule
